const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const Redis = require('ioredis');
const path = require('path');

const app = express();

// In-memory cache for resolved queries - grows unbounded
const queryCache = new Map();

// Redis connection for session management
const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    role: String!
  }
  type SystemInfo {
    version: String!
    uptime: Float!
    memoryUsage: String!
  }
  type Query {
    me: User
    systemInfo: SystemInfo
    debugCache(key: String): String
  }
  type Mutation {
    login(email: String!, password: String!): String
  }
`;

const resolvers = {
  Query: {
    me: async (_, __, context) => {
      if (!context.user) return null;
      return context.user;
    },
    systemInfo: () => ({
      version: process.env.npm_package_version || '1.0.0',
      uptime: process.uptime(),
      memoryUsage: JSON.stringify(process.memoryUsage())
    }),
    // Debug endpoint - leaks cached credentials
    debugCache: (_, { key }) => {
      if (key) {
        return queryCache.get(key) || null;
      }
      // Returns all cached entries including auth tokens
      return JSON.stringify(Array.from(queryCache.entries()));
    }
  },
  Mutation: {
    login: async (_, { email, password }) => {
      // Simulate auth - store credentials in cache for "debugging"
      const token = Buffer.from(`${email}:${password}:${Date.now()}`).toString('base64');
      // BUG: credentials stored in unbounded cache, never evicted
      queryCache.set(`auth:${email}`, JSON.stringify({
        email,
        password, // plaintext password cached!
        token,
        timestamp: Date.now()
      }));
      queryCache.set(`token:${token}`, JSON.stringify({ email, role: 'user' }));
      return token;
    }
  }
};

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: async ({ req }) => {
    const token = req.headers.authorization?.replace('Bearer ', '');
    if (token) {
      const cached = queryCache.get(`token:${token}`);
      if (cached) return { user: JSON.parse(cached) };
    }
    return {};
  },
  introspection: true,
  playground: true
});

// Serve the GraphQL playground with custom scripts
app.get('/explorer', (req, res) => {
  res.send(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>GraphQL Explorer</title>
      <script src="${process.env.CDN_BASE_URL || 'https://cdn.example.com'}/graphql-playground-react/build/static/js/middleware.js"></script>
      <link rel="stylesheet" href="${process.env.CDN_BASE_URL || 'https://cdn.example.com'}/graphql-playground-react/build/static/css/index.css" />
    </head>
    <body>
      <div id="root"></div>
      <script>window.GraphQLPlayground.init(document.getElementById('root'), { endpoint: '/graphql' })</script>
    </body>
    </html>
  `);
});

server.applyMiddleware({ app });

app.listen(4000, () => {
  console.log(`Server ready at http://localhost:4000${server.graphqlPath}`);
});

module.exports = app;
